style:
/* 青领 —— 通栏青蓝带 + 圆徽模块标题，社区模板包 */

/* ── 页首通栏色带：负外边距铺到纸边，右侧斜纹用一层 no-repeat 背景压在最右 34% ── */
.tw-qingling.resume-paper .paper-flow::before {
  content: "细心从每一个小细节开始";
  display: block;
  height: 9.8mm;
  margin: -15mm -15mm 6.2mm;
  padding: 0 15mm;
  background-color: var(--paper-accent);
  background-image: repeating-linear-gradient(105deg, transparent 0 2.6mm, rgba(255, 255, 255, 0.9) 2.6mm 4mm);
  background-position: right center;
  background-size: 34% 100%;
  background-repeat: no-repeat;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 500;
  letter-spacing: 0.16em;
  line-height: 9.8mm;
  print-color-adjust: exact;
}

/* ── 页眉：姓名与求职意向同一行，联系方式压到下一条分隔线下 ── */
.tw-qingling.resume-paper .paper-header {
  margin-bottom: 5.6mm;
}

.tw-qingling.resume-paper .paper-header--photo {
  align-items: center;
  gap: 7mm;
}

.tw-qingling.resume-paper .paper-header__main {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 6mm;
}

.tw-qingling.resume-paper .paper-name-row {
  flex: 0 0 auto;
}

.tw-qingling.resume-paper .paper-name {
  color: #213039;
  font-size: calc(var(--paper-base-size) * 1.95);
  font-weight: 700;
}

.tw-qingling.resume-paper .paper-identity {
  color: var(--paper-accent);
}

.tw-qingling.resume-paper .paper-role {
  flex: 0 0 auto;
  margin-top: 0;
  color: #213039;
  font-size: calc(var(--paper-base-size) * 1.06);
  font-weight: 600;
}

.tw-qingling.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #67767f;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.94);
}

.tw-qingling.resume-paper .paper-header__summary {
  flex: 1 0 100%;
}

/* profile 版式的联系方式本来是两列网格，这里当 flex 子项铺满整行再切三列。 */
.tw-qingling.resume-paper .paper-contacts--labeled {
  flex: 1 0 100%;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.8mm 4mm;
  margin-top: 5.4mm;
  padding: 3.2mm 0 4.4mm;
  border-top: none;
  border-bottom: 1px solid #e2eaec;
  color: #33424a;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-qingling.resume-paper .paper-contact__label {
  color: var(--paper-accent);
}

/* ── 证件照：圆形双环 ── */
.tw-qingling.resume-paper .paper-photo {
  width: 26mm;
  height: 26mm;
  border: 0.6mm solid var(--paper-accent);
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 0.9mm #fff, 0 0 0 1.5mm color-mix(in srgb, var(--paper-accent) 38%, #fff);
  print-color-adjust: exact;
}

.tw-qingling.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--paper-accent) 10%, #fff);
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.7);
  font-weight: 600;
}

/* ── 模块标题：实心圆徽 + 中文标题 + 英文副名 + 通栏浅线 ── */
.tw-qingling.resume-paper .paper-style-icon .paper-section__title {
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.12);
  letter-spacing: 0.04em;
}

.tw-qingling.resume-paper .paper-style-icon .paper-section__icon {
  width: 6.4mm;
  height: 6.4mm;
  border-color: var(--paper-accent);
  background: var(--paper-accent);
  color: #fff;
}

/* ::after 已被内置的虚线占用，英文副名用 ::before 排在标题后、分隔线前。 */
.tw-qingling.resume-paper .paper-style-icon .paper-section__title::before {
  order: 1;
  margin-left: 1.6mm;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 0.84);
  font-weight: 400;
  letter-spacing: 0.12em;
}

.tw-qingling.resume-paper .paper-style-icon .paper-section__title::after {
  order: 2;
  border-top: 1px solid #dde6e9;
}

.tw-qingling.resume-paper .is-job_intention .paper-section__title::before { content: "Intention"; }
.tw-qingling.resume-paper .is-education .paper-section__title::before { content: "Education"; }
.tw-qingling.resume-paper .is-work_experience .paper-section__title::before { content: "Experience"; }
.tw-qingling.resume-paper .is-project_experience .paper-section__title::before { content: "Projects"; }
.tw-qingling.resume-paper .is-campus_experience .paper-section__title::before { content: "Campus"; }
.tw-qingling.resume-paper .is-skills_summary .paper-section__title::before { content: "Skills"; }
.tw-qingling.resume-paper .is-skill_proficiency .paper-section__title::before { content: "Proficiency"; }
.tw-qingling.resume-paper .is-self_evaluation .paper-section__title::before { content: "Evaluation"; }
.tw-qingling.resume-paper .is-paper_publication .paper-section__title::before { content: "Papers"; }
.tw-qingling.resume-paper .is-portfolio .paper-section__title::before { content: "Portfolio"; }
.tw-qingling.resume-paper .is-postgraduate_info .paper-section__title::before { content: "Postgraduate"; }
.tw-qingling.resume-paper .is-competition .paper-section__title::before { content: "Contest"; }
.tw-qingling.resume-paper .is-award .paper-section__title::before { content: "Awards"; }
.tw-qingling.resume-paper .is-certificate .paper-section__title::before { content: "Certificates"; }
.tw-qingling.resume-paper .is-journal_paper .paper-section__title::before { content: "Journals"; }
.tw-qingling.resume-paper .is-hobby .paper-section__title::before { content: "Interests"; }

/* ── 条目：日期 / 单位 / 职位同一行三段铺开 ── */
.tw-qingling.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 5mm;
  row-gap: 0.8mm;
}

.tw-qingling.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-qingling.resume-paper .paper-item > .paper-item-head {
  flex: 0 1 auto;
  justify-content: flex-start;
  gap: 5mm;
}

.tw-qingling.resume-paper .paper-item > .paper-item-sub {
  flex: 0 0 auto;
  margin-top: 0;
  margin-left: auto;
  color: #213039;
  font-weight: 600;
}

.tw-qingling.resume-paper .paper-item-period {
  order: -1;
  color: #2c3b44;
  font-size: calc(var(--paper-base-size) * 0.96);
  font-weight: 600;
}

.tw-qingling.resume-paper .paper-item-title {
  color: #213039;
}

/* 主修课程在参考稿里是一句普通正文，不是标签胶囊。 */
.tw-qingling.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  color: #33424a;
  font-weight: 600;
}

.tw-qingling.resume-paper .paper-note__tag::after {
  content: "：";
}

/* ── 收束色带：页脚铺到左右纸边，只改 padding 不动 margin-top（分页压缩间距靠它） ── */
.tw-qingling.resume-paper .paper-footer {
  margin-left: -15mm;
  margin-right: -15mm;
  padding: 2.8mm 15mm;
  border-top: none;
  background: var(--paper-accent);
  color: #fff;
  print-color-adjust: exact;
}
